Thanks. Can you help me with 2 more things?

1. Did the main menu show any yellow WebGPU warning before you clicked Play?

2. Open the Console, paste this, click on the output to expand it, and copy and paste the expanded output.

    (async () => {
      const adapter = await navigator.gpu?.requestAdapter({ powerPreference: 'high-performance' })
      let deviceOk = false
      try {
        const device = adapter && await adapter.requestDevice({
          requiredLimits: { maxBufferSize: adapter.limits.maxBufferSize }
        })
        deviceOk = !!device
      } catch {}
      console.log({
        browser: navigator.userAgent,
        hasWebGPU: !!navigator.gpu,
        hasAdapter: !!adapter,
        deviceOk,
        adapterInfo: adapter?.info ?? null,
        isFallback: adapter?.isFallbackAdapter ?? null,
        limits: adapter ? {
          maxBufferSize: adapter.limits.maxBufferSize,
          maxSampledTexturesPerShaderStage: adapter.limits.maxSampledTexturesPerShaderStage,
          maxTextureArrayLayers: adapter.limits.maxTextureArrayLayers
        } : null
      })
    })()
